pub const RULES: &[Rule] = &[
    Rule {
        id: "G34.score_from_scoring",
        areas: "G34",
        title: r#"The scoring plays add up to the final score"#,
        checked: r#"SELECT COUNT(*) FROM log_games g WHERE EXISTS (SELECT 1 FROM log_games__scoring s WHERE s._parent = g._row)"#,
        failures: r#"SELECT 'game' AS what, game AS id, year AS year, 'final ' || final || ', the last scoring play left ' || last_scoring AS says FROM (
SELECT g._row AS game, g.season AS year, g.home_pts || '-' || g.away_pts AS final, (SELECT s.after FROM log_games__scoring s WHERE s._parent = g._row ORDER BY s._i DESC LIMIT 1) AS last_scoring
       FROM log_games g WHERE EXISTS (SELECT 1 FROM log_games__scoring s WHERE s._parent = g._row)
        AND (SELECT s.after FROM log_games__scoring s WHERE s._parent = g._row ORDER BY s._i DESC LIMIT 1) <> json_array(g.home_pts, g.away_pts))"#,
        needs: G,
        why: r#"Each game's last scoring play leaves the score at the final; a gap means a score the scoring list missed (a safety or a return) or a final changed after play."#,
    },
    Rule {
        id: "G34.box_points",
        areas: "G34",
        title: r#"Each team's box score points equal its final score"#,
        checked: r#"SELECT COUNT(*) FROM log_games__box"#,
        failures: r#"SELECT 'game' AS what, game AS id, year AS year, side || ': box points ' || points || ' against the final ' || final AS says FROM (
SELECT g._row AS game, g.season AS year, b._i AS side, b.points, CASE b._i WHEN 0 THEN g.home_pts ELSE g.away_pts END AS final
       FROM log_games__box b JOIN log_games g ON g._row = b._parent WHERE COALESCE(b.points, 0) <> CASE b._i WHEN 0 THEN g.home_pts ELSE g.away_pts END)"#,
        needs: G,
        why: r#"The box score's points and the game's final are written from the same game, so they must agree."#,
    },
    Rule {
        id: "G34.players_attempts",
        areas: "G34",
        title: r#"Player pass attempts add up to the team's"#,
        checked: r#"SELECT COUNT(*) FROM log_games__box"#,
        failures: r#"SELECT 'game' AS what, game AS id, year AS year, side || ' (' || team || '): ' || players AS says FROM (
SELECT g._row AS game, g.season AS year, b._i AS side, b.att AS team, (SELECT SUM(COALESCE(p.att, 0)) FROM log_games__players p WHERE p._parent = b._parent AND p._i = b._i) AS players
       FROM log_games__box b JOIN log_games g ON g._row = b._parent
      WHERE EXISTS (SELECT 1 FROM log_games__players p WHERE p._parent = b._parent) AND COALESCE(b.att, 0) <> (SELECT SUM(COALESCE(p.att, 0)) FROM log_games__players p WHERE p._parent = b._parent AND p._i = b._i))"#,
        needs: G,
        why: r#"Every pass attempt is credited to a passer, so the player lines sum to the team line."#,
    },
    Rule {
        id: "G34.drives_plays",
        areas: "G34",
        title: r#"Drive points add up to the offense's points"#,
        checked: r#"SELECT COUNT(*) FROM log_games__box b WHERE EXISTS (SELECT 1 FROM log_games__drives d WHERE d._parent = b._parent)"#,
        failures: r#"SELECT 'game' AS what, game AS id, year AS year, side || ': drives ' || drive_points || ' plus defensive touchdowns ' || defense_tds || ' against ' || points AS says FROM (
SELECT g._row AS game, g.season AS year, b._i AS side, (SELECT SUM(COALESCE(d.points, 0)) FROM log_games__drives d WHERE d._parent = b._parent AND COALESCE(d.team, 0) = b._i) AS drive_points,
            b.points, COALESCE(b.def_td, 0) AS defense_tds
       FROM log_games__box b JOIN log_games g ON g._row = b._parent
      WHERE EXISTS (SELECT 1 FROM log_games__drives d WHERE d._parent = b._parent)
        AND (SELECT SUM(COALESCE(d.points, 0)) FROM log_games__drives d WHERE d._parent = b._parent AND COALESCE(d.team, 0) = b._i) > COALESCE(b.points, 0))"#,
        needs: G,
        why: r#"A drive's points can never add to more than the team scored (return and defensive scores come on top, so fewer is fine)."#,
    },
];

